use forge_domain :: Transformer ; use crate :: dto :: anthropic :: Request ; use forge_domain :: { Context , ContextMessage , ModelId , ToolDefinition , Transformer } ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Converts a tool name from the internal `mcp_{server}_tool_{tool}` format to"] # [doc = " the Claude Code `mcp__{server}__{tool}` format."] # [doc = ""] # [doc = " Uses the last occurrence of `_tool_` as the server/tool separator to"] # [doc = " correctly handle server names that themselves contain `_tool_` as a"] # [doc = " substring. Names that do not match the internal format are returned"] # [doc = " unchanged."] fn to_claude_code_format (name : & str) -> String { let Some (rest) = name . strip_prefix ("mcp_") else { return name . to_string () ; } ; if let Some ((server , tool)) = rest . rsplit_once ("_tool_") { return format ! ("mcp__{server}__{tool}") ; } name . to_string () }